begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1716 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2d37f163346ec0dd009ba51d' and md5(to_jsonb(t)::text)='78061e58eea1f075d09a2abaa8de9389')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2d37f163346ec0dd009ba51d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2d37f163346ec0dd009ba51d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2ff65e228901f70ca8f98828' and md5(to_jsonb(t)::text)='5c77ab7d4852ab394f6be0803c7d8c47')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2ff65e228901f70ca8f98828';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6a176a5460d3e0d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa y tengas la capucha puesta, las pruebas de Sabiduría (Percepción) que se hagan para verte tendrán desventaja y tú tendrás ventaja en las pruebas de Destreza (Sigilo) que hagas para esconderte, ya que el color de la capa cambia para camuflarte. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6a176a5460d3e0d9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2ff65e228901f70ca8f98828';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:30656091b999872276793afc' and md5(to_jsonb(t)::text)='ae96f8a7f27d1b7ddba58cd4a2dc9f0e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:30656091b999872276793afc';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ff5772d0bc461b80$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta esfera de hierro oxidada mide 7,5 cm de diámetro y pesa 0,5 kg. Puedes usar una acción para pronunciar la palabra de activación y lanzar la esfera contra una criatura Enorme o más pequeña que puedas ver a 18 m o menos de ti. En el recorrido del lanzamiento, la esfera se abre en una maraña de bandas de metal.\n\nRealiza una tirada de ataque a distancia con un bonificador de ataque igual a tu modificador por Destreza más tu bonificador por competencia. Si impactas, el objetivo quedará apresado hasta que utilices una acción adicional para volver a pronunciar la palabra de activación y liberarlo. Si haces esto o si el ataque yerra, las bandas se contraerán y volverán a convertirse en una esfera.\n\nCualquier criatura, incluida la que está apresada, puede emplear una acción para realizar una prueba de Fuerza con CD 20 y romper las bandas de hierro. Si la supera, el objeto se destruye y la criatura apresada se libera. Si la falla, cualquier otro intento de romper las bandas por parte de la criatura fallará automáticamente hasta que hayan transcurrido 24 horas.\n\nUna vez que se utilizan las bandas, no podrán volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ff5772d0bc461b80$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:30656091b999872276793afc';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:31e133f12be930aa336bc88c' and md5(to_jsonb(t)::text)='6bc0613c508d44f67a272b3a1ee48535')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:31e133f12be930aa336bc88c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bbdf4b4486601b3b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este yelmo tiene 3 cargas. Mientras lo lleves puesto, podrás utilizar una acción y gastar 1 carga para lanzar el conjuro teletransporte desde él. El yelmo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bbdf4b4486601b3b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:31e133f12be930aa336bc88c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:34cbbbaf34a6ecc0fd73e8ca' and md5(to_jsonb(t)::text)='e340d29db1e981ac5ccf564e02e51b1e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:34cbbbaf34a6ecc0fd73e8ca';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:34cbbbaf34a6ecc0fd73e8ca';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3534fedcf685dcdcbdddaa6c' and md5(to_jsonb(t)::text)='0bccee3c102e2ea134f1e0d7968d809c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3534fedcf685dcdcbdddaa6c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_05f5187d34948d72$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este calzado ligero, podrás moverte hacia arriba, hacia abajo y de lado por superficies verticales, así como boca abajo por techos. Esta manera de moverse no requiere del uso de las manos, que quedan libres. Tienes una velocidad trepando igual a tu velocidad caminando. No obstante, las babuchas no te permiten desplazarte de esta forma por una superficie resbaladiza, como una zona cubierta por hielo o aceite.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_05f5187d34948d72$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3534fedcf685dcdcbdddaa6c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:35b4956012293b51dbd948f2' and md5(to_jsonb(t)::text)='ab9b21fc52271bc54682e65e2cf834ae')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:35b4956012293b51dbd948f2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_47ab4ab81b1e6ae0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta pesada bolsa de tela contiene 3d4 judías blancas. La bolsa pesa 250 g más 125 g por cada judía que contenga.\n\nSi tiras el contenido de la bolsa al suelo, explotará en un radio de 3 m alrededor de las judías. Todas las criaturas situadas en la zona, incluyéndote a ti, deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 5d4 de daño de fuego si la fallan o la mitad del daño si la superan. Los objetos inflamables de la zona arderán siempre y cuando no los lleve o vista alguien.\n\nSi sacas una judía de la bolsa, la plantas en tierra o arena y la riegas, la judía producirá un efecto 1 minuto después en el suelo donde la hayas plantado. Tu GM puede elegir el efecto de la siguiente tabla, determinarlo al azar o crear uno nuevo.\n\n01 · Brotan 5d4 hongos venenosos. Si una criatura come un hongo, tira un dado. Si el resultado es impar, la criatura deberá superar una tirada de salvación de Constitución con CD 15 o recibirá 5d6 de daño de veneno y quedará envenenada durante 1 hora. Si el resultado es par, la criatura obtendrá 5d6 puntos de golpe temporales que durarán 1 hora.\n02–10 · Un géiser emerge del suelo y expulsa a borbotones agua, cerveza, zumo de bayas, té, vinagre, vino o aceite (a elección de tu GM). El chorro tiene una altura de 9 m y dura 1d12 asaltos.\n11–20 · Un ent brota del suelo. Hay un 50 % de probabilidad de que sea caótico malvado y ataque.\n21–30 · Surge una estatua de piedra animada e inmóvil con tu apariencia que te amenaza verbalmente. Si la abandonas y otros se acercan, la estatua te describirá como el más vil de los villanos y mandará a los recién llegados a buscarte y atacarte. Si estás en el mismo plano de existencia que la estatua, sabrá donde estás. La estatua se volverá inanimada al cabo de 24 horas.\n31–40 · Surge una hoguera de llamas azules que arderá durante 24 horas (o hasta que la apaguen).\n41–50 · 1d6 + 6 chillones brotan del suelo.\n51–60 · 1d4 + 8 sapos de color rosa intenso salen del suelo. Si alguien toca uno de los sapos, este se transforma en un monstruo Grande o más pequeño a elección de tu GM. El monstruo permanece durante 1 minuto y luego desaparece en una nube de humo rosa intenso.\n61–70 · Un bulette hambriento sale de la tierra y ataca.\n71–80 · Crece un árbol frutal. Tiene 1d10 + 20 piezas de fruta, de las cuales 1d8 tienen los efectos de pociones determinadas al azar y otra de ellas funciona como un veneno ingerido a elección de tu GM. El árbol se desvanece tras 1 hora. La fruta recogida permanece y conserva la magia durante 30 días.\n81–90 · Aparece un nido con 1d4 + 3 huevos. Cualquier criatura que se coma uno de estos huevos deberá realizar una tirada de salvación de Constitución con CD 20. Si la supera, aumentará su puntuación de característica más baja en 1 de forma permanente (se elegirá al azar la puntuación si hay varias puntuaciones que empatan como la más baja). Si la falla, la criatura recibirá 10d6 de daño de fuerza debido a una explosión mágica interna.\n91–99 · Una pirámide con una base cuadrada de 18 m de lado emerge del suelo. En el interior hay un sarcófago que contiene a un señor de las momias. La pirámide se considera la guarida del señor de las momias y su sarcófago alberga un tesoro a elección de tu GM.\n00 · Brota un tallo de judías gigante que crece hasta la altura que decida tu GM, que también elige adónde conduce la parte superior. Por ejemplo, podría dar a un hermoso mirador, al castillo de un gigante de las nubes o a otro plano de existencia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_47ab4ab81b1e6ae0$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:35b4956012293b51dbd948f2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:372fde0046c3e7c354b9b95a' and md5(to_jsonb(t)::text)='0371f55917e490df3525f45af33dbb70')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:372fde0046c3e7c354b9b95a';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5e2c0c85cd829724$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta cuerda mide 9 m de largo y pesa 1,5 kg. Si sujetas uno de los extremos de la cuerda y utilizas una acción para pronunciar su palabra de activación, el otro extremo saldrá disparado hacia delante para enredar a una criatura que puedas ver a 6 m o menos de ti. El objetivo deberá superar una tirada de salvación de Destreza con CD 15 o quedará apresado.\n\nPuedes liberar a la criatura si usas una acción adicional para pronunciar una segunda palabra de activación. Un objetivo apresado por la cuerda puede utilizar una acción para realizar una prueba de Fuerza o Destreza (a elección del objetivo) con CD 15. Si la supera, la criatura dejará de estar apresada.\n\nLa cuerda tiene una CA de 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda se reducen a 0, se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5e2c0c85cd829724$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:372fde0046c3e7c354b9b95a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:38070df72830c84b3b5c4bea' and md5(to_jsonb(t)::text)='e4c19acfafe7385d41ec3ca085c81ac2')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:38070df72830c84b3b5c4bea';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:38070df72830c84b3b5c4bea';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3873f56f6673d7d6a8e03ffb' and md5(to_jsonb(t)::text)='09f2fb67821668f0af0028bbe3a6af6c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3873f56f6673d7d6a8e03ffb';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_28be7e6ab30b84f7$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro detectar pensamientos (CD de salvación 13). En el líquido denso y morado de la poción flota una nube rosa ovoide.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_28be7e6ab30b84f7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3873f56f6673d7d6a8e03ffb';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:39453ee81afcebaacb6be012' and md5(to_jsonb(t)::text)='ea3c8b19a5342149c19561e50ecf21c0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:39453ee81afcebaacb6be012';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f210f5b75e2cfc57$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada tela negra, suave como la seda, está doblada para tener las dimensiones de un pañuelo. Al desdoblarla, se convierte en una sábana circular de 1,8 m de diámetro.\n\nPuedes utilizar una acción para extender un agujero portátil y colocarlo sobre una superficie sólida o apoyado en ella, donde creará un agujero extradimensional de 3 m de profundidad. El espacio cilíndrico en el interior del agujero se encuentra en otro plano, así que no sirve para crear pasadizos. Cualquier criatura que esté en el interior de un agujero portátil abierto podrá salir de él escalando.\n\nPuedes utilizar una acción para cerrar un agujero portátil sujetando los bordes de la tela y doblándola. Al doblar la tela se cierra el agujero y cualquier criatura u objeto que haya en su interior permanecerá en el espacio extradimensional. Independientemente de su contenido, el agujero no pesa casi nada.\n\nSi se dobla, las criaturas que haya dentro del espacio extradimensional del agujero podrán utilizar una acción para realizar una prueba de Fuerza con CD 10. Si la superan, se abrirán paso hacia la salida y aparecerán a 1,5 m o menos del agujero portátil o de la criatura que lo lleve consigo. Si se mete dentro del agujero portátil a una criatura que necesite respirar, podrá sobrevivir durante 10 minutos; después, empezará a ahogarse.\n\nMeter un agujero portátil en el espacio extradimensional creado por una bolsa de contención, un morral práctico o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f210f5b75e2cfc57$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:39453ee81afcebaacb6be012';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:397f56a255aa64b959bb17ad' and md5(to_jsonb(t)::text)='fd1269fb22c1bb3702d9de12a3ec2877')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:397f56a255aa64b959bb17ad';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bdb52a76377c1eea$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:397f56a255aa64b959bb17ad';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:399d2fabfaca062f022b9259' and md5(to_jsonb(t)::text)='46fdca39091b3e8d658975446bd2e078')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:399d2fabfaca062f022b9259';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b0fdb5e9b42a7c29$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:399d2fabfaca062f022b9259';
