if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3a81c2f6a557d09b39518381' and md5(to_jsonb(t)::text)='e5abf271c157c6913312d8ffd47423b8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3a81c2f6a557d09b39518381';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3041fc769c486f0c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa guarda un parecido superficial con una bolsa de contención, pero en realidad es el orificio de alimentación de una criatura extradimensional gigante. Poner la bolsa del revés cierra el orificio.\n\nLa criatura extradimensional vinculada a la bolsa puede sentir cualquier cosa que se meta en su interior y devora cualquier materia animal o vegetal que se introduzca por completo. Esta materia se pierde para siempre. Cuando se introduce parte de una criatura viva en la bolsa, como cuando alguien mete la mano, hay un 50 % de probabilidad de que toda la criatura se vea arrastrada al interior. Una criatura que esté dentro de la bolsa puede utilizar su acción para tratar de escapar superando una prueba de Fuerza con CD 15. Otra criatura puede utilizar su acción para meter la mano en la bolsa con el fin de sacar a una criatura, lo que logrará si supera una prueba de Fuerza con CD 20 (siempre y cuando no vaya a parar ella también al interior de la bolsa primero). Cualquier criatura que comience su turno en el interior de la bolsa será devorada y su cuerpo será destruido.\n\nSe pueden guardar objetos inanimados en la bolsa, que puede albergar 0,03 m3 de dicho material. No obstante, una vez al día, la bolsa se traga cualquier objeto que contenga y lo escupe en otro plano de existencia. Tu GM determina el momento y el plano.\n\nSi se perfora o se rasga la bolsa, se destruye y cualquier cosa que contenga se transporta a un lugar aleatorio del Plano Astral.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3041fc769c486f0c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3a81c2f6a557d09b39518381';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3b1581c937cbc58988d337c0' and md5(to_jsonb(t)::text)='945ca7e9e3e4aafd1218451de3f562b9')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3b1581c937cbc58988d337c0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f90f6a78613d875c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes a un infernal o muerto viviente con esta arma mágica, esa criatura recibirá 2d6 de daño radiante adicional. Si al objetivo le quedan 25 puntos de golpe o menos tras sufrir este daño, deberá superar una tirada de salvación de Sabiduría con CD 15 o será destruido. Si la supera, la criatura quedará asustada de ti hasta el final de tu siguiente turno.\n\nMientras empuñes esta arma, emitirá luz brillante en un radio de 6 m y luz tenue 6 m más allá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f90f6a78613d875c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3b1581c937cbc58988d337c0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3b8581124ebb69e0130f882e' and md5(to_jsonb(t)::text)='4c7ff3c01f0ac643338b1b51fdfedd50')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3b8581124ebb69e0130f882e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$text_49e3e80c25fd1c94$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3b8581124ebb69e0130f882e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3ba334460d1fc2fa2a8a2a56' and md5(to_jsonb(t)::text)='fa0b6171eb88053a33fcbb6b9ce2a59c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3ba334460d1fc2fa2a8a2a56';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_a5e60adaef5e7214$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa de aspecto ordinario, hecha de tela de color gris, rojizo o marrón, parece vacía. No obstante, meter la mano en su interior revela la presencia de un objeto pequeño y peludo. La bolsa pesa 250 g.\n\nPuedes usar una acción para sacar el objeto peludo de la bolsa y lanzarlo a 6 m o menos de distancia. Cuando aterrice, se transformará en la criatura que determines al tirar 1d8 y consultar la tabla que corresponda al color de la bolsa. La criatura desaparecerá al siguiente amanecer o cuando sus puntos de golpe se reduzcan a 0.\n\nLa criatura es amistosa contigo y tus compañeros y actúa en tu turno. Puedes emplear una acción adicional para decirle cómo debe moverse y qué acción debe realizar en su turno o para darle órdenes más generales, como atacar a tus enemigos. Si no recibe tales órdenes, se comportará conforme a su naturaleza.\n\nUna vez que se han extraído tres objetos peludos de la bolsa, no puede volver a utilizarse hasta el siguiente amanecer. Bolsa de trucos gris\n\n1 · Comadreja\n2 · Rata gigante\n3 · Tejón\n4 · Jabalí\n5 · Pantera\n6 · Tejón gigante\n7 · Lobo terrible\n8 · Alce gigante\n\nBolsa de trucos rojiza\n\n1 · Rata\n2 · Búho\n3 · Mastín\n4 · Cabra\n5 · Cabra gigante\n6 · Jabalí gigante\n7 · León\n8 · Oso pardo\n\nBolsa de trucos marrón\n\n1 · Chacal\n2 · Simio\n3 · Babuino\n4 · Pico de hacha\n5 · Oso negro\n6 · Comadreja gigante\n7 · Hiena gigante\n8 · Tigre\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a5e60adaef5e7214$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3ba334460d1fc2fa2a8a2a56';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3c51a3c091c8f10097310716' and md5(to_jsonb(t)::text)='2c8a465057914515c7c2b430dc0a38f4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3c51a3c091c8f10097310716';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_908dfa734a103f7e$"Objeto · Precio base · Peso\nPetate · 1 po · 7 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_908dfa734a103f7e$::jsonb,true),'{rules,definition,description}',$text_31b34ce008f3ab23$[{"id":"official-table","rows":[["Petate","1 po","7 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_31b34ce008f3ab23$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:3c51a3c091c8f10097310716';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3d024672d426c959fbf7c9a1' and md5(to_jsonb(t)::text)='fe84b7686ab91f1a376a9960515d1a85')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3d024672d426c959fbf7c9a1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_a48bd797ee9953ab$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tubo contiene un líquido lechoso con un fuerte olor a alcohol. Puedes utilizar una acción para verter el contenido del tubo en una superficie que esté a tu alcance. El líquido disolverá de manera instantánea hasta 0,1 m2 de adhesivo que toque, incluido el pegamento soberano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a48bd797ee9953ab$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3d024672d426c959fbf7c9a1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3d2325ab1ac5aaf2b05117b8' and md5(to_jsonb(t)::text)='e337be77057fb0bbefe6b4f09abfdd7c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3d2325ab1ac5aaf2b05117b8';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_8c5c5e9c9d1e0814$"Objeto · Precio base · Peso\nAntitoxina (vial) · 50 po · —\n\nAntitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_8c5c5e9c9d1e0814$::jsonb,true),'{features}',$text_0f739e268f820ed0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_0f739e268f820ed0$::jsonb,true),'{rules,definition,description}',$text_a38957a8694717e6$[{"id":"official-table","rows":[["Antitoxina (vial)","50 po","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a38957a8694717e6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:3d2325ab1ac5aaf2b05117b8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3d3aec52c044be52dd2ff23f' and md5(to_jsonb(t)::text)='60b3334cd5b6a2c786464bb2ca4eea32')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3d3aec52c044be52dd2ff23f';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_3ef3ef49987bd5fd$[{"id":"official-base-table","rows":[["Estoque","25 po","2 lb","1d8 perforante","+0","Sutil"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_3ef3ef49987bd5fd$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_0af07ecc566352fb$["official-base-table","property-finesse","family-rule"]$text_0af07ecc566352fb$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:3d3aec52c044be52dd2ff23f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3e000ccfb949f6041bdb6785' and md5(to_jsonb(t)::text)='f292b58ec2c92c84128162f9198446d8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3e000ccfb949f6041bdb6785';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4e2d72052ae5caa6$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de diplomático (39 po). Incluye un cofre, 2 estuches para mapas o pergaminos, una muda de ropas de calidad, una botella de tinta, una pluma, una lámpara, 2 frascos de aceite, 5 hojas de papel, un vial de perfume, lacre y jabón.\n\nDuración: Según su uso..","showInActions":false}]$text_4e2d72052ae5caa6$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3e000ccfb949f6041bdb6785';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:3f024215021b8d6d2f55ce10' and md5(to_jsonb(t)::text)='b68e3980679e037ecab92f2f444c1489')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:3f024215021b8d6d2f55ce10';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_16212da8d792cdb7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este polvo, que se encuentra en recipientes pequeños, se asemeja a arena muy fina. Parece ser polvo de desaparición y un conjuro identificar lo reconocerá como tal. Hay suficiente para un solo uso.\n\nCuando utilices una acción para esparcir un puñado de polvo por el aire, tú y todas las criaturas que necesiten respirar y estén a 9 m o menos de ti deberéis superar una tirada de salvación de Constitución con CD 15 o seréis incapaces de respirar mientras estornudáis de manera incontrolable. Una criatura que sufra este efecto quedará incapacitada y se asfixiará. Mientras permanezca consciente, podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. El conjuro restablecimiento menor también puede poner fin a este efecto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_16212da8d792cdb7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:3f024215021b8d6d2f55ce10';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:40a2f5363de51d6cb164abd8' and md5(to_jsonb(t)::text)='a3a76f2626eb69615b58e599399d9e73')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:40a2f5363de51d6cb164abd8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_218cded44c006dc6$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos brazales, serás competente con arcos cortos y largos y obtendrás un bonificador de +2 a las tiradas de daño en ataques a distancia con estas armas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_218cded44c006dc6$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:40a2f5363de51d6cb164abd8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:40b58116d37541a913e599f0' and md5(to_jsonb(t)::text)='a706269897a34bca989d761cff4ecdb5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:40b58116d37541a913e599f0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_916ef2de428fdc28$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras sostengas este escudo, podrás emplear una acción adicional para pronunciar su palabra de activación y darle vida. El escudo saltará de tu mano y levitará en tu espacio para protegerte como si lo embrazaras, pero dejará tus manos libres. Permanecerá animado durante 1 minuto, hasta que utilices una acción adicional para poner fin a este efecto o hasta que quedes incapacitado o mueras, momento en el que el escudo caerá al suelo o en tu mano si tienes una libre.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_916ef2de428fdc28$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:40b58116d37541a913e599f0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:40c309135dcff04c75eaedf9' and md5(to_jsonb(t)::text)='fcc835c130cb82aa645648457b89c6cc')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:40c309135dcff04c75eaedf9';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_185896a0dd0385ab$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Mientras la lleves puesta, podrás utilizar una acción y emplear 1 carga para hacer que la prenda muestre un patrón cambiante de tonos y formas deslumbrantes hasta el final de tu siguiente turno. Durante este tiempo, la túnica emite luz brillante en un radio de 9 m y luz tenue 9 m más allá. Las criaturas que puedan verte tendrán desventaja en las tiradas de ataque contra ti. Además, cualquier criatura que esté bajo la luz brillante y pueda verte cuando el poder de la túnica esté activo deberá superar una tirada de salvación de Sabiduría con CD 15 o quedará aturdida hasta que termine el efecto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_185896a0dd0385ab$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:40c309135dcff04c75eaedf9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:412fed1c4f5ada1768df781f' and md5(to_jsonb(t)::text)='ebf31f81074c2a3efe38f1c193ae2027')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:412fed1c4f5ada1768df781f';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_5ff59ab7045a4e5a$[{"id":"official-base-table","rows":[["Látigo","2 po","3 lb","1d4 cortante","+0","Sutil, Gran alcance"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_5ff59ab7045a4e5a$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bbdc1a34540faeb5$["official-base-table","property-finesse","property-reach","family-rule"]$text_bbdc1a34540faeb5$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:412fed1c4f5ada1768df781f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4174a78b2371715a4e15dc13' and md5(to_jsonb(t)::text)='97b2c68f9aed55697573b8153b38542d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4174a78b2371715a4e15dc13';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_0ad8ef062dea31c7$[{"id":"official-base-table","rows":[["Tridente","5 po","4 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_0ad8ef062dea31c7$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_0170730ceade80f6$["official-base-table","property-thrown","property-versatile","family-rule"]$text_0170730ceade80f6$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:4174a78b2371715a4e15dc13';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:42c6717f4067f757367c2635' and md5(to_jsonb(t)::text)='6d1006aff2cffe2ebe937d288f9cc4f8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:42c6717f4067f757367c2635';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_936a5b5b3051a619$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción para pronunciar su palabra de activación. Cuando lo hagas, podrás ver a través de la materia sólida durante 1 minuto. Esta visión tiene un radio de 9 m. Para ti, los objetos sólidos que haya dentro de ese radio se verán transparentes y no impedirán el paso de la luz. La visión puede atravesar 30 cm de piedra, 2,5 cm de cualquier metal común o hasta 90 cm de madera o tierra. Las sustancias más gruesas o una lámina fina de plomo bloquearán la visión.\n\nSi usas el anillo de nuevo antes de completar un descanso largo, deberás superar una tirada de salvación de Constitución con CD 15 o sumarás un nivel de cansancio.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_936a5b5b3051a619$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:42c6717f4067f757367c2635';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:43724e0ebf8db032ebc00277' and md5(to_jsonb(t)::text)='b65b1bf2118db8f2f8aa108bbad44788')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:43724e0ebf8db032ebc00277';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_b10e6701beb43d7a$[{"id":"official-base-table","rows":[["Ballesta pesada","50 po","18 lb","1d10 perforante","+0","Munición, Pesada, Recarga, A dos manos","100/400"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_b10e6701beb43d7a$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_c915daa13e229fb5$["official-base-table","property-ammunition","property-heavy","property-loading","property-two-handed","family-rule"]$text_c915daa13e229fb5$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:43724e0ebf8db032ebc00277';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:43b466967fe1635949e68f69' and md5(to_jsonb(t)::text)='74980c93db7119d3ace40ca382defa44')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:43b466967fe1635949e68f69';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_26b0744f6151c5c6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando coloques una flecha en este arco, susurrará en élfico: “Pronta derrota para mis enemigos”. Al utilizar esta arma para hacer un ataque a distancia, puedes decir lo siguiente como frase de activación: “Pronta muerte a aquellos que me han perjudicado”. El objetivo de tu ataque se convertirá en tu enemigo jurado hasta que muera o hasta que amanezca siete días después. Solo puedes tener un enemigo jurado a la vez. Cuando muera, podrás elegir otro después del siguiente amanecer.\n\nCuando realices una tirada de ataque a distancia con esta arma contra tu enemigo jurado, tendrás ventaja. Asimismo, tu objetivo no obtendrá ningún beneficio de la cobertura, salvo que sea cobertura completa, y tú no tendrás desventaja debido al alcance largo. Si el ataque impacta, tu enemigo jurado sufrirá 3d6 de daño perforante adicional.\n\nMientras tu enemigo jurado esté vivo, tendrás desventaja en las tiradas de ataque con el resto de armas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_26b0744f6151c5c6$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:43b466967fe1635949e68f69';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:43ba30e7be7c03faaaaff52c' and md5(to_jsonb(t)::text)='5be5e8a37b81667513a0987e91b82c10')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:43ba30e7be7c03faaaaff52c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_b9c12384f0a795a9$[{"id":"official-base-table","rows":[["Hoz","1 po","2 lb","1d4 cortante","+0","Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_b9c12384f0a795a9$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_a0bde6997c52c8d2$["official-base-table","property-light","family-rule"]$text_a0bde6997c52c8d2$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:43ba30e7be7c03faaaaff52c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:452141c2dd6546ad7efa6fbf' and md5(to_jsonb(t)::text)='b0a946351b708ba44a9bb0d236548224')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:452141c2dd6546ad7efa6fbf';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c3e9f02eb41659a4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta pequeña esfera negra mide 2 cm de diámetro y pesa 30 g. Normalmente, se encuentran 1d4 + 4 canicas de fuerza juntas.\n\nPuedes utilizar una acción para lanzar la canica a 18 m o menos de distancia. La canica explotará al impactar y se destruirá. Todas las criaturas en un radio de 3 m del punto de impacto deberán superar una tirada de salvación de Destreza con CD 15 o sufrirán 5d4 de daño de fuerza. Después, el área quedará encerrada en una esfera de fuerza transparente durante 1 minuto. Las criaturas que hayan fallado la tirada de salvación y estén dentro del área por completo quedarán atrapadas en el interior de la esfera. A las criaturas que hayan superado la tirada o que estén dentro del área solo parcialmente se las empujará lejos del centro de la esfera hasta que dejen de estar en su interior. A través de la pared de la esfera solo puede pasar el aire respirable, ningún otro ataque o efecto.\n\nUna criatura encerrada puede usar su acción para empujar la pared de la esfera y hacerla moverse a hasta la mitad de la velocidad caminando de la criatura. La esfera se puede recoger y su magia hace que solo pese 0,5 kg, independientemente de lo que pesen las criaturas que contenga.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_c3e9f02eb41659a4$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:452141c2dd6546ad7efa6fbf';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:456584ec47f3232d734253f5' and md5(to_jsonb(t)::text)='6cc4681485277dcc1492e704941d1729')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:456584ec47f3232d734253f5';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6135e49522279479$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 3 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 carga para lanzar el conjuro detectar magia desde ella. La varita recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6135e49522279479$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:456584ec47f3232d734253f5';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:45c8ee7602d853f90c15821e' and md5(to_jsonb(t)::text)='42f4009e2a1bba4a0a41e1853a43b1e6')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:45c8ee7602d853f90c15821e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5a9cb890c2682564$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 10 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón pierde sus propiedades y se convierte en un bastón no mágico.\n\nConjuros. Puedes usar una acción y gastar 1 o más de las cargas del bastón para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: despertar (5 cargas), encantar animal (1 carga), hablar con las plantas (3 cargas), hablar con los animales (1 carga), localizar animales o plantas (2 cargas), muro de espinas (6 cargas) o piel robliza (2 cargas).\n\nTambién puedes usar una acción para lanzar el conjuro pasar sin rastro desde el bastón sin gastar ninguna carga.\n\nForma de árbol. Puedes utilizar una acción para plantar un extremo del bastón en tierra fértil y gastar 1 carga para transformarlo en un árbol sano. El árbol mide 18 m de alto, el diámetro de su tronco es de 1,5 m y las ramas de su copa cubren un radio de 6 m. El árbol parece normal, pero un conjuro detectar magia revela que irradia una débil aura de magia de transmutación. Si tocas el árbol y utilizas otra acción para pronunciar su palabra de activación, el bastón recuperará su forma normal. Cualquier criatura que se encuentre en el árbol caerá cuando recupere su forma de bastón.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5a9cb890c2682564$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:45c8ee7602d853f90c15821e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:460da7e8ff13313e9f1f24ea' and md5(to_jsonb(t)::text)='4ad09dad2eac8ce5247769dc1c05a942')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:460da7e8ff13313e9f1f24ea';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_710aa5ba9966d542$"Objeto · Precio base · Peso\nRopas comunes · 5 pp · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_710aa5ba9966d542$::jsonb,true),'{rules,definition,description}',$text_8b249a8c7a296f12$[{"id":"official-table","rows":[["Ropas comunes","5 pp","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_8b249a8c7a296f12$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:460da7e8ff13313e9f1f24ea';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:467d1b7be14f7d6b4b56ac69' and md5(to_jsonb(t)::text)='68dec8fbc44233b1efb069e95e7734f8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:467d1b7be14f7d6b4b56ac69';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b8dcea00ba896e6e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos brazales, obtendrás un bonificador de +2 a la CA si no vistes ninguna armadura ni embrazas ningún escudo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b8dcea00ba896e6e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:467d1b7be14f7d6b4b56ac69';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:46f6e5386a87b70724f56073' and md5(to_jsonb(t)::text)='77c42d5a876094a6630403ba0ac145b0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:46f6e5386a87b70724f56073';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_36e1dcb196e25803$[{"id":"legacy-bonus-0","kind":"passive","name":"SpellAttackModifier","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador de +2 a las tiradas de ataque de hechizos y a las CD de las tiradas de salvación de tus hechizos.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este talismán es un poderoso símbolo del bien. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño radiante si lo toca. En cambio, si es de alineamiento malvado, sufrirá 8d6 de daño radiante. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín bueno, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 7 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento malvado, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se diseminará en unas motas de luz dorada y se destruirá.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_36e1dcb196e25803$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:46f6e5386a87b70724f56073';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:47a6d04d7d3433823f7e134c' and md5(to_jsonb(t)::text)='c07277c4d61c2df02f30cc9103c74ee8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:47a6d04d7d3433823f7e134c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_10f8d6157d7b74b1$"Objeto · Precio base · Peso\nGarfio de escalada · 2 po · 4 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_10f8d6157d7b74b1$::jsonb,true),'{rules,definition,description}',$text_69e1bde7e5d5a2e9$[{"id":"official-table","rows":[["Garfio de escalada","2 po","4 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_69e1bde7e5d5a2e9$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:47a6d04d7d3433823f7e134c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4833ddfcc70fc5283f6e5e6a' and md5(to_jsonb(t)::text)='f79da222684866965330d78f570551d7')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4833ddfcc70fc5283f6e5e6a';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_90ccabafddf4b31b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando se mira de forma indirecta este espejo de 1,2 m de altura, su superficie muestra imágenes tenues de criaturas. El espejo pesa 25 kg y tiene una CA de 11, 10 puntos de golpe y vulnerabilidad al daño contundente. Se hace pedazos y se destruye cuando sus puntos de golpe se reducen a 0.\n\nSi el espejo cuelga de una superficie vertical y te encuentras a 1,5 m o menos de él, podrás usar una acción para pronunciar su palabra de activación. Permanecerá activado hasta que uses una acción para repetir la palabra de activación.\n\nSi una criatura distinta de ti ve su reflejo en el espejo activado a 9 m o menos de ella, deberá superar una tirada de salvación de Carisma con CD 15 o quedará atrapada, junto con todo lo que vista o lleve, en una de las doce celdas extradimensionales del espejo. Esta tirada de salvación se realiza con ventaja si la criatura conoce la naturaleza del espejo. Los autómatas superan la tirada de salvación automáticamente.\n\nUna celda extradimensional es una extensión infinita cubierta por una espesa niebla que impide ver a más de 3 m de distancia. Las criaturas atrapadas en las celdas del espejo no envejecen y no necesitan ni comer ni beber ni dormir. Pueden escapar de la celda si utilizan magia que les permita viajar entre planos. De lo contrario, quedarán confinadas en la celda hasta que las liberen.\n\nSi el espejo atrapa a una criatura, pero sus doce celdas extradimensionales están ya ocupadas, liberará a una criatura atrapada al azar para alojar al nuevo prisionero. La criatura liberada aparecerá en un espacio sin ocupar a la vista del espejo, pero de espaldas a él. Si se destruye el espejo, todas las criaturas que contenga se liberarán y aparecerán en espacios sin ocupar cerca de él.\n\nMientras te encuentres a 1,5 m o menos del espejo, podrás usar una acción para pronunciar el nombre de una criatura atrapada o el número de una celda concreta. La criatura mencionada o la que contenga la celda nombrada aparecerá como una imagen en la superficie del espejo. La criatura y tú os podréis comunicar con normalidad.\n\nDel mismo modo, puedes usar una acción para pronunciar una segunda palabra de activación y liberar a una criatura atrapada en el espejo. La criatura liberada aparecerá junto a sus posesiones en el espacio sin ocupar más cercano al espejo, pero de espaldas a él.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_90ccabafddf4b31b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4833ddfcc70fc5283f6e5e6a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:48a1fa2051aaf151a240831d' and md5(to_jsonb(t)::text)='8d06cdda5f45266ffedde86b3a0ee28d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:48a1fa2051aaf151a240831d';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_d1ecfa231bd5fa2d$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nEspada corta feroz · 10 po (solo objeto mundano base; no es el precio de la variante mágica) · 2 lb · 1d6 perforante · Sutil, Ligera · +0\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_d1ecfa231bd5fa2d$::jsonb,true),'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_9f9043892b11f9c3$[{"id":"official-table","rows":[["Espada corta feroz","10 po (solo objeto mundano base; no es el precio de la variante mágica)","2 lb","1d6 perforante","Sutil, Ligera","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_9f9043892b11f9c3$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:48a1fa2051aaf151a240831d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4a0280fe1a12b371b774bf9f' and md5(to_jsonb(t)::text)='a3ddfd1b94475dca7dd82ce4bcd5e773')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4a0280fe1a12b371b774bf9f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b986d16dfcc6755e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este colgante, serás inmune a todas las enfermedades. Si ya te has contagiado de alguna, se contendrán sus efectos mientras lleves el colgante.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b986d16dfcc6755e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4a0280fe1a12b371b774bf9f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4a02f0cda8f345e2b24656d0' and md5(to_jsonb(t)::text)='4e62894c09f2633103ea6d775a71a840')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4a02f0cda8f345e2b24656d0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_18e6126021f5b235$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a una criatura con esta arma mágica y saques un 20 en la tirada de ataque, el objetivo sufrirá 3d6 de daño necrótico adicional si no es un autómata o un muerto viviente. Además, obtendrás una cantidad de puntos de golpe temporales igual al daño adicional infligido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_18e6126021f5b235$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4a02f0cda8f345e2b24656d0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4a6120b4d5686829d8c8e4e2' and md5(to_jsonb(t)::text)='e387b8ac1ee8248da2edaa2bd176befc')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4a6120b4d5686829d8c8e4e2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4a6120b4d5686829d8c8e4e2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4ab721eddc176d100836952d' and md5(to_jsonb(t)::text)='3e936c5eb27ff4fbaec85170587e14ee')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4ab721eddc176d100836952d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3d5a61b219de9b2f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estas lentes oscuras, tienes visión en la oscuridad hasta 18 m. Si ya posees visión en la oscuridad, estos anteojos aumentan su alcance en 18 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d5a61b219de9b2f$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4ab721eddc176d100836952d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4c62e49d5acef27730cb5b42' and md5(to_jsonb(t)::text)='0618a303c4af53e193dac3f4d32d4087')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4c62e49d5acef27730cb5b42';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4c62e49d5acef27730cb5b42';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4e36e183be0438f40795afb1' and md5(to_jsonb(t)::text)='ca38548a7aab152e20619f9b7d99f141')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4e36e183be0438f40795afb1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_372092bb7cf63a5a$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, podrás utilizar una acción adicional para entrechocar los talones. Si lo haces, las botas duplicarán tu velocidad caminando y cualquier criatura que realice un ataque de oportunidad contra ti sufrirá desventaja en la tirada de ataque. Si vuelves a entrechocar los talones, el efecto terminará.\n\nCuando hayas usado esta propiedad de las botas durante un total de 10 minutos, la magia dejará de funcionar hasta que finalices un descanso largo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_372092bb7cf63a5a$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4e36e183be0438f40795afb1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4e54b43480349f37ef196d17' and md5(to_jsonb(t)::text)='399ba44d3799a61ccd5d9bb9e9d2ce14')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4e54b43480349f37ef196d17';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_c15551ec8d633855$"Objeto · Precio base · Peso\nYesquero · 5 pp · 1 lb\n\nYesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_c15551ec8d633855$::jsonb,true),'{features}',$text_bd65b4d01e3d68ec$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_bd65b4d01e3d68ec$::jsonb,true),'{rules,definition,description}',$text_814298e44215c03b$[{"id":"official-table","rows":[["Yesquero","5 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_814298e44215c03b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:4e54b43480349f37ef196d17';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:4f1318f7cc6681bdee47447e' and md5(to_jsonb(t)::text)='45dec82c2945bfdd043325f74a88aaf9')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:4f1318f7cc6681bdee47447e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3941bd8d941bb415$[{"id":"scrying","kind":"action","name":"Escudriñar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La bola de cristal clásica es un objeto muy raro que mide unos 15 cm de diámetro. Mientras la tocas, puedes lanzar el conjuro escudriñar (CD de salvación 17).\n\nDuración: Según el conjuro..\n\nConcentración: sí.","showInActions":true}]$text_3941bd8d941bb415$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:4f1318f7cc6681bdee47447e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:505f80662d56ffa3adb212b7' and md5(to_jsonb(t)::text)='2ea058146351990a8173aa4798403015')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:505f80662d56ffa3adb212b7';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ffeec24cc9187eb8$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:505f80662d56ffa3adb212b7';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:50efd0e45ac3503fcd5c510e' and md5(to_jsonb(t)::text)='f30ecf09c6cd86fc0620fa1dc9142478')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:50efd0e45ac3503fcd5c510e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_607fc5801291eb71$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este sombrero, podrás utilizar una acción para lanzar a voluntad el conjuro disfrazarse desde él. El conjuro termina si te quitas el sombrero.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_607fc5801291eb71$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:50efd0e45ac3503fcd5c510e';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 12 as batch,53 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;